import React from 'react';

function App() {
    return (
        <div className="p-8">
            <h1 className="text-3xl font-bold text-blue-600">School Directory System</h1>
            <p className="mt-4 text-gray-600">Frontend is running successfully!</p>
            <button 
                onClick={() => fetch('http://localhost:8000/')}
                className="mt-4 px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
            >
                Test Backend Connection
            </button>
        </div>
    );
}

export default App;
